$ErrorActionPreference = "Stop"

$root = Get-Location
if (-not (Test-Path (Join-Path $root ".git"))) {
    throw "Run this script from the SakhtYar repository root."
}

Write-Host ""
Write-Host "============================================================" -ForegroundColor Cyan
Write-Host " SakhtYar - Premium UI + Development Demo Seed" -ForegroundColor Cyan
Write-Host "============================================================" -ForegroundColor Cyan

function Write-Base64Utf8([string]$RelativePath, [string]$Base64) {
    $path = Join-Path $root $RelativePath
    $parent = Split-Path $path -Parent
    if (-not (Test-Path $parent)) {
        New-Item -ItemType Directory -Force -Path $parent | Out-Null
    }
    [System.IO.File]::WriteAllBytes($path, [Convert]::FromBase64String($Base64))
    Write-Host ("  updated: " + $RelativePath) -ForegroundColor DarkGreen
}

function Read-Utf8([string]$Path) {
    [System.IO.File]::ReadAllText(
        $Path,
        (New-Object System.Text.UTF8Encoding($false))
    )
}

function Write-Utf8([string]$Path, [string]$Text) {
    [System.IO.File]::WriteAllText(
        $Path,
        $Text,
        (New-Object System.Text.UTF8Encoding($false))
    )
}

# -------------------------------------------------------------------------
# Backup touched source files locally. Nothing is deleted from Docker.
# -------------------------------------------------------------------------
$stamp = Get-Date -Format "yyyyMMdd-HHmmss"
$backupRoot = Join-Path $root ".local\patch-backups\premium-ui-demo-seed-$stamp"
New-Item -ItemType Directory -Force -Path $backupRoot | Out-Null

$files = @{}
$files["backend\modules\casefile\src\main\java\com\sakhtyar\casefile\domain\CaseStatus.java"] = "cGFja2FnZSBjb20uc2FraHR5YXIuY2FzZWZpbGUuZG9tYWluOwoKcHVibGljIGVudW0gQ2FzZVN0YXR1cyB7CiAgICBEUkFGVCwKICAgIE5FR09USUFUSU9OLAogICAgQ09OVFJBQ1QsCiAgICBDT05TVFJVQ1RJT04sCiAgICBBQ1RJVkUsCiAgICBDT01QTEVURUQsCiAgICBPTl9IT0xELAogICAgQVJDSElWRUQKfQo="
$files["backend\modules\casefile\src\main\java\com\sakhtyar\casefile\domain\CaseEntity.java"] = ""
$files["backend\modules\casefile\src\main\java\com\sakhtyar\casefile\api\CaseDtos.java"] = ""
$files["backend\modules\casefile\src\main\java\com\sakhtyar\casefile\application\CaseService.java"] = ""
$files["backend\app\src\main\resources\db\migration\V8__case_cover_image.sql"] = "QUxURVIgVEFCTEUgY29uc3RydWN0aW9uX2Nhc2UKICAgIEFERCBDT0xVTU4gSUYgTk9UIEVYSVNUUyBjb3Zlcl9pbWFnZV91cmwgVkFSQ0hBUigxMDAwKTsKCkNSRUFURSBJTkRFWCBJRiBOT1QgRVhJU1RTIGlkeF9jb25zdHJ1Y3Rpb25fY2FzZV9zdGF0dXNfdXBkYXRlZAogICAgT04gY29uc3RydWN0aW9uX2Nhc2Uoc3RhdHVzLCB1cGRhdGVkX2F0IERFU0MpOwo="
$files["backend\app\src\main\resources\db\dev\seed-demo.sql"] = ""
$files["backend\app\src\main\java\com\sakhtyar\bootstrap\DevSeedRunner.java"] = ""
$files["frontend\src\pages\LoginPage.tsx"] = ""
$files["frontend\src\app\AppShell.tsx"] = ""
$files["frontend\src\pages\CasesPage.tsx"] = ""
$files["frontend\src\pages\UsersPage.tsx"] = ""
$files["frontend\src\pages\CaseDetailPage.tsx"] = ""
$files["frontend\src\styles\global.css"] = ""
$files["frontend\src\ui\antdTheme.ts"] = ""

Write-Host ""
Write-Host "[1/7] Backing up and writing source files..." -ForegroundColor Cyan

foreach ($relativePath in $files.Keys) {
    $source = Join-Path $root $relativePath
    if (Test-Path $source) {
        $backup = Join-Path $backupRoot $relativePath
        $backupParent = Split-Path $backup -Parent
        New-Item -ItemType Directory -Force -Path $backupParent | Out-Null
        Copy-Item $source $backup -Force
    }
    Write-Base64Utf8 $relativePath $files[$relativePath]
}

# -------------------------------------------------------------------------
# Patch frontend API type without replacing the rest of api/types.ts.
# -------------------------------------------------------------------------
Write-Host ""
Write-Host "[2/7] Updating frontend API types..." -ForegroundColor Cyan

$typesPath = Join-Path $root "frontend\src\api\types.ts"
$types = Read-Utf8 $typesPath

$types = [regex]::Replace(
    $types,
    "export type CaseStatus = 'DRAFT' \| 'ACTIVE' \| 'ARCHIVED'",
    "export type CaseStatus =`n  | 'DRAFT'`n  | 'NEGOTIATION'`n  | 'CONTRACT'`n  | 'CONSTRUCTION'`n  | 'ACTIVE'`n  | 'COMPLETED'`n  | 'ON_HOLD'`n  | 'ARCHIVED'"
)

if ($types -notmatch 'coverImageUrl\?:') {
    $types = $types.Replace(
        "  landAreaM2?: number | null`n",
        "  landAreaM2?: number | null`n  coverImageUrl?: string | null`n"
    )
}

Write-Utf8 $typesPath $types
Write-Host "  updated: frontend\src\api\types.ts" -ForegroundColor DarkGreen

# -------------------------------------------------------------------------
# Configure development seed. Global default is OFF; local profile default ON.
# -------------------------------------------------------------------------
Write-Host ""
Write-Host "[3/7] Configuring development seed switch..." -ForegroundColor Cyan

$appYmlPath = Join-Path $root "backend\app\src\main\resources\application.yml"
$appYml = Read-Utf8 $appYmlPath

# Keep shared/default environments safe.
if ($appYml -notmatch '(?m)^\s{2}dev-seed:\s*$') {
    $needle = "app:`r`n"
    if (-not $appYml.Contains($needle)) {
        $needle = "app:`n"
    }
    $insert = "app:`r`n  dev-seed:`r`n    enabled: `${APP_DEV_SEED_ENABLED:false}`r`n"
    $appYml = $appYml.Replace($needle, $insert)
}

# Include current IntelliJ frontend port.
$appYml = $appYml.Replace(
    "http://localhost:5173,http://localhost:5174,http://localhost:3000",
    "http://localhost:5175,http://localhost:5173,http://localhost:5174,http://localhost:3000"
)

# Avoid corrupted fallback display-name in source config.
$appYml = [regex]::Replace(
    $appYml,
    '(?m)^\s{4}display-name:\s*\$\{APP_BOOTSTRAP_ADMIN_DISPLAY_NAME:[^}]*\}\s*$',
    '    display-name: ${APP_BOOTSTRAP_ADMIN_DISPLAY_NAME:System Administrator}'
)

Write-Utf8 $appYmlPath $appYml

$localYmlPath = Join-Path $root "backend\app\src\main\resources\application-local.yml"
$localYml = Read-Utf8 $localYmlPath

if ($localYml -notmatch '(?m)^\s{2}dev-seed:\s*$') {
    $localYml = $localYml.TrimEnd() + @"

  dev-seed:
    enabled: `${APP_DEV_SEED_ENABLED:true}
"@
}

Write-Utf8 $localYmlPath ($localYml.TrimEnd() + "`r`n")

# Local .env: enable seed unless user already made a choice.
$envPath = Join-Path $root ".env.observability.local"
if (Test-Path $envPath) {
    $envText = Get-Content $envPath -Raw
    if ($envText -notmatch '(?m)^\s*APP_DEV_SEED_ENABLED\s*=') {
        Add-Content -Path $envPath -Value "`r`nAPP_DEV_SEED_ENABLED=true"
    }
}

$exampleEnvPath = Join-Path $root ".env.observability.local.example"
if (Test-Path $exampleEnvPath) {
    $exampleText = Get-Content $exampleEnvPath -Raw
    if ($exampleText -notmatch '(?m)^\s*APP_DEV_SEED_ENABLED\s*=') {
        Add-Content -Path $exampleEnvPath -Value "`r`nAPP_DEV_SEED_ENABLED=true"
    }
}

# Startup reporter link -> current frontend port.
$reporterPath = Join-Path $root "backend\app\src\main\java\com\sakhtyar\bootstrap\LocalStartupReporter.java"
if (Test-Path $reporterPath) {
    $reporter = Read-Utf8 $reporterPath
    $reporter = $reporter.Replace("http://localhost:5173", "http://localhost:5175")
    Write-Utf8 $reporterPath $reporter
}

Write-Host "  APP_DEV_SEED_ENABLED: default false, local default true" -ForegroundColor Green

# -------------------------------------------------------------------------
# Ensure local generated/backup folders stay outside Git.
# -------------------------------------------------------------------------
Write-Host ""
Write-Host "[4/7] Updating .gitignore for local-only files..." -ForegroundColor Cyan

$gitignorePath = Join-Path $root ".gitignore"
$gitignore = if (Test-Path $gitignorePath) { Get-Content $gitignorePath -Raw } else { "" }

foreach ($entry in @("/.local/docker-images/", "/.local/patch-backups/")) {
    if ($gitignore -notmatch [regex]::Escape($entry)) {
        $gitignore += "`r`n$entry"
    }
}

Write-Utf8 $gitignorePath ($gitignore.Trim() + "`r`n")

# -------------------------------------------------------------------------
# Validate frontend.
# -------------------------------------------------------------------------
Write-Host ""
Write-Host "[5/7] Building frontend..." -ForegroundColor Cyan

Push-Location (Join-Path $root "frontend")
try {
    npm run build
    if ($LASTEXITCODE -ne 0) {
        throw "Frontend build failed."
    }
}
finally {
    Pop-Location
}

# -------------------------------------------------------------------------
# Validate backend.
# -------------------------------------------------------------------------
Write-Host ""
Write-Host "[6/7] Compiling backend..." -ForegroundColor Cyan

Push-Location (Join-Path $root "backend")
try {
    mvn -q -pl app -am -DskipTests compile
    if ($LASTEXITCODE -ne 0) {
        throw "Backend compile failed."
    }
}
finally {
    Pop-Location
}

# -------------------------------------------------------------------------
# Git diff check only. Do NOT commit or push.
# -------------------------------------------------------------------------
Write-Host ""
Write-Host "[7/7] Final checks..." -ForegroundColor Cyan

git diff --check
if ($LASTEXITCODE -ne 0) {
    throw "git diff --check failed."
}

